                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and out[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            box = (min(ys), max(ys), min(xs), max(xs))
            if len(cells) == (box[1] - box[0] + 1) * (box[3] - box[2] + 1):
                patches[color].append(box)

    # A color used in exactly four center patches is a marker color. When the
    # four patches occupy rectangle corners, extend their full sides through gaps.
    for color, boxes in patches.items():
        boxes = set(boxes)
        if len(boxes) != 4:
            continue
        row_bands = sorted({(b[0], b[1]) for b in boxes})
        col_bands = sorted({(b[2], b[3]) for b in boxes})
        if len(row_bands) != 2 or len(col_bands) != 2:
            continue
        top, bottom = row_bands
        left, right = col_bands
        corners = {(top[0], top[1], left[0], left[1]),
                   (top[0], top[1], right[0], right[1]),
                   (bottom[0], bottom[1], left[0], left[1]),
                   (bottom[0], bottom[1], right[0], right[1])}
        if boxes != corners:
            continue
        # Join the corresponding rows of the top and bottom patches.
        for y in range(top[0], top[1] + 1):
            for x in range(left[1] + 1, right[0]):
                if out[y][x] == 0:
                    out[y][x] = color
        for y in range(bottom[0], bottom[1] + 1):
            for x in range(left[1] + 1, right[0]):
